<?php
declare(strict_types=1);require_once __DIR__.'/../config/auth.php';page_require(['ADMIN','VERIFICADOR']);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reportes — Hache Natación</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fa;font-family:Manrope,Arial,sans-serif;color:#172033}.wrap{max-width:1040px;margin:auto;padding:82px 14px 32px}h1{margin:0 0 5px}.sub{color:#64748b;margin-bottom:18px}.toolbar{display:flex;gap:8px;align-items:center;background:#fff;padding:12px;border-radius:14px;margin-bottom:14px}.toolbar input,.toolbar button,.toolbar a{padding:10px;border-radius:9px;border:1px solid #cbd5e1;font:inherit}.toolbar button{background:#172033;color:#fff;font-weight:800}.toolbar a{background:#e8eef2;color:#172033;text-decoration:none;font-weight:800}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.card,.panel,.proa{background:#fff;border-radius:15px;padding:15px;box-shadow:0 3px 12px #0f172a0d}.n{font-size:24px;font-weight:900}.l{font-size:11px;color:#64748b;text-transform:uppercase;font-weight:800}.panel,.proa{margin-top:12px}.proa-grid{display:grid;grid-template-columns:1fr 1fr 1.3fr;gap:12px}.proa-box{padding:14px;border:1px solid #e5eaf0;border-radius:13px}.progress{height:13px;background:#e5e7eb;border-radius:999px;overflow:hidden;margin:10px 0 7px}.progress>span{display:block;height:100%;background:#123b5d;border-radius:999px}.ok{color:#166534;font-weight:900}.pending{color:#92400e;font-weight:900}.formula{margin-top:10px;color:#64748b;font-size:12px;line-height:1.5}.error-box{grid-column:1/-1;padding:14px;border:1px solid #fecaca;background:#fff1f2;color:#991b1b;border-radius:12px;font-weight:700}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px;border-bottom:1px solid #eef2f7;font-size:13px}@media(max-width:760px){.toolbar{flex-wrap:wrap}.toolbar input{flex:1 1 100%}.toolbar button,.toolbar a{flex:1}.cards{grid-template-columns:1fr 1fr}.proa-grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Reportes</h1><div class="sub">Liquidación mensual Hache Natación · PROA Nadadores</div><div class="toolbar"><input id="periodo" type="month"><button id="ver">Actualizar</button><a id="csv">Exportar CSV</a></div><div id="cards" class="cards"></div><section class="proa"><h3>Convenio Hache · PROA</h3><div id="proa" class="proa-grid"></div><div class="formula">PROA recibe 50% de mensualidades + 50% de cursos intensivos + 100% de inscripciones. Hache recibe 50% de mensualidades + 50% de cursos intensivos. El mínimo de $28,000 habilita las comisiones del mes siguiente.</div></section><div class="panel"><h3>Historial mensual</h3><table><thead><tr><th>Periodo</th><th>Total cobrado</th><th>Hache</th><th>PROA</th><th>Mínimo</th></tr></thead><tbody id="meses"></tbody></table></div><div class="panel"><h3>Asistencia del mes</h3><div id="asis"></div></div></main><script>const p=document.getElementById('periodo'),c=document.getElementById('cards'),pm=document.getElementById('proa'),m=document.getElementById('meses'),a=document.getElementById('asis'),csv=document.getElementById('csv');p.value=new Date().toISOString().slice(0,7);const money=n=>Number(n||0).toLocaleString('es-MX',{style:'currency',currency:'MXN'});function showError(msg){c.innerHTML=`<div class="error-box">No se pudo cargar el reporte: ${String(msg||'Error desconocido')}</div>`;pm.innerHTML='';m.innerHTML='<tr><td colspan="5">Sin datos</td></tr>';a.textContent='Sin datos';}async function load(){try{c.innerHTML='<div class="card"><div class="l">Cargando reporte…</div></div>';const r=await fetch(`/api/reportes.php?periodo=${encodeURIComponent(p.value)}`,{cache:'no-store'});const raw=await r.text();let x;try{x=JSON.parse(raw)}catch(_){throw new Error(raw||`HTTP ${r.status}`)}if(!r.ok||!x.ok)throw new Error(x.error||`HTTP ${r.status}`);c.innerHTML=`<div class="card"><div class="n">${money(x.finanzas.total)}</div><div class="l">Total cobrado</div></div><div class="card"><div class="n">${money(x.finanzas.mensualidades_total)}</div><div class="l">Mensualidades</div></div><div class="card"><div class="n">${money(x.finanzas.inscripciones_total)}</div><div class="l">Inscripciones</div></div><div class="card"><div class="n">${money(x.finanzas.intensivos_total)}</div><div class="l">Cursos intensivos</div></div>`;const q=x.convenio_proa;pm.innerHTML=`<div class="proa-box"><div class="l">Participación Hache</div><div class="n">${money(q.hache)}</div></div><div class="proa-box"><div class="l">Participación PROA</div><div class="n">${money(q.proa)}</div></div><div class="proa-box"><div class="l">Mínimo PROA</div><div class="progress"><span style="width:${q.progreso}%"></span></div>${q.alcanzado?`<div class="ok">Mínimo alcanzado ✓</div>`:`<div class="pending">${money(q.proa)} de ${money(q.minimo)}</div><div>Faltan ${money(q.faltante)}</div>`}</div>`;m.innerHTML=x.meses.map(z=>`<tr><td>${z.periodo}</td><td>${money(z.total)}</td><td>${money(z.hache)}</td><td>${money(z.proa)}</td><td>${z.minimo_alcanzado?'✓ Alcanzado':'Pendiente'}</td></tr>`).join('')||'<tr><td colspan="5">Sin datos</td></tr>';a.textContent=`Presentes: ${x.asistencia.presentes||0} · Justificadas: ${x.asistencia.justificadas||0} · No justificadas: ${x.asistencia.no_justificadas||0}`;csv.href=`/api/reportes-exportar.php?desde=${x.desde}&hasta=${x.hasta}`;}catch(e){showError(e.message)}}document.getElementById('ver').onclick=load;p.onchange=load;load();</script></body></html>